package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import android.provider.*;import java.io.*;import java.util.*;import org.json.*;

final class ImportWork {
    static final int FOLDER=86;
    static void enqueue(Activity a,List<Uri> files,long subject,boolean books){if(files.isEmpty()){PlusUi.toast(a,"Nenhum ficheiro recebido.");return;}ClipData clip=ClipData.newRawUri("Seeky",files.get(0));for(int n=1;n<files.size();n++)clip.addItem(new ClipData.Item(files.get(n)));Intent data=new Intent().addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);data.setClipData(clip);selected(a,data,subject,books);}
    static void selected(Activity a,Intent data,long subject,boolean books){List<Uri> selected=StudyImporter.selected(data);if(selected.isEmpty()){PlusUi.toast(a,"O selector não devolveu ficheiros.");return;}PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create("import",books?"Importar livros":"Importar materiais",new JSONObject().put("subject",subject).put("books",books).put("scan_complete",true));android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{int at=0;for(Uri uri:selected){if(uri!=null)permission(a,uri,data.getFlags());db.add(id,at++,uri==null?"":uri.toString(),"",0,0);}db.totals(id);sql.setTransactionSuccessful();}finally{sql.endTransaction();}}final String job=id;TaskService.launch(a,job);});}
    static void permission(Context c,Uri uri,int flags){if((flags&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0)try{c.getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(RuntimeException ignored){}}
    static void pickFolder(MainActivity a,boolean books){a.getSharedPreferences("studies",0).edit().putBoolean("import_folder_books",books).putLong("import_folder_subject",books?0:a.studies.subject).apply();try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),FOLDER);}catch(Exception e){PlusUi.error(a,e);}}
    static void folder(Activity a,Intent data,long subject,boolean books){Uri root=data.getData();if(root==null)return;permission(a,root,data.getFlags());enqueueFolder(a,root,subject,books);}
    static void enqueueFolder(Activity a,Uri root,long subject,boolean books){PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create("import","Verificar pasta",new JSONObject().put("subject",subject).put("books",books).put("tree",root.toString()).put("scan_complete",false));Uri document=DocumentsContract.buildDocumentUriUsingTree(root,DocumentsContract.getTreeDocumentId(root));db.getWritableDatabase().insertOrThrow("scan_nodes",null,StudyStore.values("job",id,"uri",document.toString()));db.getWritableDatabase().insertWithOnConflict("folders",null,StudyStore.values("uri",root.toString(),"name",DocumentsContract.getTreeDocumentId(root),"subject",subject,"workspace",TaskStore.workspace(a)),android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}final String job=id;TaskService.launch(a,job);});}
    static void folders(Activity a){PlusUi.run(a,()->{List<StudyStore.Row> rows=new ArrayList<>();try(TaskStore db=new TaskStore(a);Cursor c=db.getReadableDatabase().query("folders",null,"workspace=?",new String[]{TaskStore.workspace(a)},null,null,"checked DESC")){while(c.moveToNext())rows.add(TaskStore.row(c));}PlusUi.post(a,()->{UiPanel p=new UiPanel(a,"Pastas de importação",null,"folder");for(StudyStore.Row r:rows)p.action("refresh",r.s("name"),"Procurar novos livros",false,()->enqueueFolder(a,Uri.parse(r.s("uri")),r.n("subject"),true));if(rows.isEmpty())p.note("Importe uma pasta na opção Livros para a verificar novamente.");p.show();});});}
    static void scan(Context c,TaskStore db,StudyStore.Row job,JSONObject data,TaskService.Control control)throws Exception{String id=job.s("id");Uri tree=Uri.parse(data.getString("tree"));int sequence=(int)db.count(id,null);for(;;){control.check();String folder=null;try(Cursor next=db.getReadableDatabase().rawQuery("SELECT uri FROM scan_nodes WHERE job=? AND done=0 LIMIT 1",new String[]{id})){if(next.moveToFirst())folder=next.getString(0);}if(folder==null)break;String folderUri=folder;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(Uri.parse(folder)));int found=0;
            try(Cursor rows=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},android.os.Bundle.EMPTY,null)){if(rows==null)throw new IOException("Sem acesso à pasta. Escolha-a novamente.");while(rows.moveToNext()){control.check();String doc=rows.getString(0),name=rows.getString(1),mime=rows.getString(2);Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,doc);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){db.getWritableDatabase().insertWithOnConflict("scan_nodes",null,StudyStore.values("job",id,"uri",uri.toString()),android.database.sqlite.SQLiteDatabase.CONFLICT_IGNORE);continue;}if(data.optBoolean("books",true)&&!BookQuery.accepts(name,mime))continue;boolean exists;try(Cursor prior=db.getReadableDatabase().rawQuery("SELECT 1 FROM items WHERE job=? AND uri=? LIMIT 1",new String[]{id,uri.toString()})){exists=prior.moveToFirst();}if(!exists)db.add(id,sequence++,uri.toString(),name,rows.isNull(3)?0:rows.getLong(3),rows.isNull(4)?0:rows.getLong(4));if(++found%25==0)control.progress("A verificar pasta · "+sequence+" ficheiros",0,0);}}
            db.getWritableDatabase().update("scan_nodes",StudyStore.values("done",1),"job=? AND uri=?",new String[]{id,folderUri});control.progress("A verificar pasta · "+sequence+" ficheiros",0,0);
        }data.put("scan_complete",true);db.payload(id,data);db.totals(id);long bytes;try(Cursor sum=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(bytes),0) FROM items WHERE job=?",new String[]{id})){sum.moveToFirst();bytes=sum.getLong(0);}db.getWritableDatabase().update("folders",StudyStore.values("checked",System.currentTimeMillis()),"uri=?",new String[]{tree.toString()});String summary=sequence+" ficheiros · "+android.text.format.Formatter.formatShortFileSize(c,bytes)+" · Retome para iniciar a importação.";control.progress(summary,0,sequence);db.state(id,"paused",summary);control.stopped=true;throw new InterruptedIOException();
    }
    static void run(Context c,StudyStore.Row job,TaskStore db,TaskService.Control control)throws Exception{JSONObject data=new JSONObject(job.s("payload"));if(!data.optBoolean("scan_complete",true))scan(c,db,job,data,control);String id=job.s("id");long subject=data.optLong("subject");try(StudyStore store=new StudyStore(c)){
        for(;;){control.check();List<StudyStore.Row> pending=db.items(id,"pending",0,1);if(pending.isEmpty())break;StudyStore.Row item=pending.get(0);int seq=(int)item.n("seq");db.item(id,seq,StudyStore.values("state","running"));try{process(c,store,db,job,item,subject,data.optBoolean("books",true),control);}catch(InterruptedIOException e){db.item(id,seq,StudyStore.values("state","pending"));throw e;}catch(Exception e){db.item(id,seq,StudyStore.values("state","failed","message",e.getMessage()==null?"Ficheiro indisponível":e.getMessage()));}db.totals(id);long done=db.count(id,"done"),duplicates=db.count(id,"duplicate"),failed=db.count(id,"failed"),total=db.count(id,null);control.progress(done+" importados · "+duplicates+" repetidos · "+failed+" falhados",done+duplicates+failed,total);StudyEvents.changed();}
    }long failed=db.count(id,"failed");if(failed>0)throw new IOException(failed+" ficheiros precisam de atenção. Os concluídos foram mantidos; pode retomar só os falhados.");CloudJobs.schedule(c);LibraryIndex.enqueue(c);}
    static boolean equalSource(Context c,Uri uri,File file,String expected,TaskService.Control control)throws Exception{if(!file.isFile())return false;java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(InputStream source=c.getContentResolver().openInputStream(uri);InputStream stored=new FileInputStream(file)){if(source==null)throw new IOException("Sem acesso ao material.");byte[] a=new byte[65536],b=new byte[65536];for(;;){control.check();int na=block(source,a,control),nb=block(stored,b,control);if(na!=nb)return false;if(na==0)break;for(int i=0;i<na;i++)if(a[i]!=b[i])return false;digest.update(a,0,na);}return WorkspaceBackup.hex(digest.digest()).equals(expected);}}
    static int block(InputStream input,byte[] data,TaskService.Control control)throws Exception{int total=0;while(total<data.length){control.check();int n=input.read(data,total,data.length-total);if(n<0)break;if(n==0)continue;total+=n;}return total;}
    static void known(TaskStore work,Context c,Uri uri,long subject,long material,String hash){work.getWritableDatabase().insertWithOnConflict("sources",null,StudyStore.values("uri",uri.toString(),"subject",subject,"workspace",TaskStore.workspace(c),"material",material,"hash",hash),android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}
    static void process(Context c,StudyStore store,TaskStore work,StudyStore.Row job,StudyStore.Row item,long subject,boolean books,TaskService.Control control)throws Exception{
        String id=job.s("id"),name=item.s("name"),mime=item.s("mime");int seq=(int)item.n("seq");Uri uri=Uri.parse(item.s("uri"));if(!Arrays.asList("content","file").contains(uri.getScheme()))throw new IOException("O selector não forneceu uma localização válida.");
if("file".equals(uri.getScheme())&&(uri.getPath()==null||!StorageAccess.allowed(c,new File(uri.getPath()))))throw new IOException("Ficheiro fora do armazenamento autorizado.");if(subject>0&&store.get("subjects",subject)==null)throw new IOException("O módulo de destino já não está disponível.");
        File target=item.s("target").isEmpty()?null:new File(item.s("target"));if(target!=null&&target.isFile()){List<StudyStore.Row> committed=store.rows("materials","path=?",new String[]{target.getPath()},null,1);if(!committed.isEmpty()){work.item(id,seq,StudyStore.values("state","done","material",committed.get(0).id(),"message","Importado"));return;}}
        if(name.isEmpty()){try(Cursor info=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(info!=null&&info.moveToFirst()){int nameColumn=info.getColumnIndex(OpenableColumns.DISPLAY_NAME),sizeColumn=info.getColumnIndex(OpenableColumns.SIZE);if(nameColumn>=0&&!info.isNull(nameColumn))name=info.getString(nameColumn);if(sizeColumn>=0&&!info.isNull(sizeColumn))work.item(id,seq,StudyStore.values("bytes",info.getLong(sizeColumn)));}}if(name==null||name.isEmpty())name="Material "+(seq+1);mime=MediaFormats.mime(name,c.getContentResolver().getType(uri));work.item(id,seq,StudyStore.values("name",name,"mime",mime));}if(mime.isEmpty())mime=MediaFormats.mime(name,c.getContentResolver().getType(uri));if(target==null){try(Cursor prior=work.getReadableDatabase().query("sources",null,"uri=? AND subject=? AND workspace=?",new String[]{uri.toString(),""+subject,TaskStore.workspace(c)},null,null,null,"1")){if(prior.moveToFirst()){long previous=prior.getLong(prior.getColumnIndexOrThrow("material"));StudyStore.Row book=store.get("materials",previous);if(book!=null&&equalSource(c,uri,new File(book.s("path")),book.s("hash"),control)){work.item(id,seq,StudyStore.values("state","duplicate","material",previous,"message","Conteúdo verificado; já existente."));return;}}}}
        if(books&&!BookQuery.accepts(name,mime))throw new IOException("Formato não suportado na estante.");File folder=StudyFileProvider.directory(c);if(target==null){target=new File(folder,"work-"+id+"-"+seq+"."+StudyFiles.extension(name));work.item(id,seq,StudyStore.values("target",target.getPath(),"mime",mime));}
        if(!DiskWalker.inside(folder.getCanonicalFile(),target.getCanonicalFile()))throw new IOException("Destino inválido.");String hash;
        if(target.isFile())hash=StudyFiles.hash(target);else{long max=DocumentBudget.available(folder,name,mime);if(item.n("bytes")>max)throw new IOException("O ficheiro excede o espaço livre ou o limite deste formato. Liberte espaço e retome.");File part=new File(target.getPath()+".part");if(part.exists()&&!part.delete())throw new IOException("Não foi possível retomar a cópia temporária.");try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Sem acesso ao material. Escolha novamente a pasta se a autorização expirou.");hash=StudyFiles.copy(in,target,max,control::cancelled);}}
        control.check();if(target.length()==0)throw new IOException("Material vazio.");List<StudyStore.Row> previous=store.rows("materials","subject=? AND hash=?",new String[]{""+subject,hash},null,20);for(StudyStore.Row old:previous){File prior=new File(old.s("path"));if(prior.isFile()&&BookDuplicates.equal(prior,target,control::cancelled)){target.delete();known(work,c,uri,subject,old.id(),hash);work.item(id,seq,StudyStore.values("state","duplicate","material",old.id(),"message","Conteúdo já existente neste destino."));return;}}
        if(!previous.isEmpty())throw new IOException("A cópia já registada está indisponível ou alterada. Reveja-a antes de retomar.");BookMetadata metadata=BookMetadata.read(c,target,name,mime);control.check();long now=System.currentTimeMillis();long material=store.save("materials",0,StudyStore.values("subject",subject,"title",metadata.title,"author",metadata.author,"name",name,"mime",mime,"path",target.getPath(),"hash",hash,"bytes",target.length(),"created",now,"updated",now));if(!metadata.series.isEmpty())try(PlusStore plus=new PlusStore(c)){plus.getWritableDatabase().execSQL("INSERT OR IGNORE INTO book_meta(hash,series) VALUES(?,?)",new Object[]{hash,metadata.series});}known(work,c,uri,subject,material,hash);work.item(id,seq,StudyStore.values("state","done","material",material,"message","Importado"));
    }
    private ImportWork(){}
}
